/* From Uiverse.io by JaydipPrajapati1910 - Tags: button, hover, hover effect */
.__UIV_SCOPE__ .container {
  width: 400px;
  height: 400px;
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  display: flex;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ .center {
  width: 180px;
  height: 60px;
  position: absolute;
}

.__UIV_SCOPE__ .btn {
  width: 180px;
  height: 60px;
  cursor: pointer;
  background: transparent;
  border: 2px solid #222;
  outline: none;
  transition: 1s ease-in-out;
}

.__UIV_SCOPE__ .btn svg {
  position: absolute;
  left: 0;
  top: 0;
  fill: none;
  stroke: #91C9FF;
  stroke-dasharray: 150 480;
  stroke-dashoffset: 150;
  transition: 1s ease-in-out;
}

.__UIV_SCOPE__ .btn:hover {
  transition: 1s ease-in-out;
  background: #4F95DA;
}

.__UIV_SCOPE__ .btn:hover span {
  transition: 1s ease-in-out;
  color: #fff;
}

.__UIV_SCOPE__ .btn:hover svg {
  stroke-dashoffset: -480;
}

.__UIV_SCOPE__ .btn span {
  color: black;
  font-size: 18px;
  font-weight: 600;
}
